 no_model_imports();guard();assert read(C/'INPUT_VALIDATION.json')['status']=='PASS';start=time.monotonic();ids=read(C8/'A08_INPUTS.json')['endpoint_content_ids'];sources=[];records=[];allkeys={};allids=set();alloriginal={};inputpaths=[];source_cache={};source_rows={};amendment=[]
 def ingest(path,kind,scope,expected_sha=None,expected_rows=None):
  path=Path(path).resolve();assert path.is_relative_to(W.resolve()) and not path.is_symlink();h=sha(path);assert not expected_sha or h==expected_sha;rs=rows(path);assert expected_rows is None or len(rs)==expected_rows;rel=str(path.relative_to(W));sid=digest({'commit':cfg['research_head_before'],'path':rel,'sha256':h});assert sid not in source_cache,'Source ingested twice';source_cache[sid]=path;source_rows[sid]=rs;inputpaths.append(path);sources.append({'source_id':sid,'path':rel,'commit':cfg['research_head_before'],'sha256':h,'bytes':path.stat().st_size,'rows':len(rs),'fields':list(rs[0]),'kind':(rs[0].get('table_kind') or kind),'scope':scope})
