 publish('TABLE_INDEX.json',{'schema':'pod-a-A09-integrated-release-v2','status':'PASS','scientific_rows':len(records),'unique_scientific_keys':len(allkeys),'kinds':dict(counts),'partitions':partitions,'source_index':'SOURCE_TABLE_INDEX.json','lossless_policy':'Compact full-precision scientific view plus exact immutable source/file/row/columns reference; original rows and statuses are never rewritten','historical_alias_repair_reused':{'path':str((D90/'ENDPOINT_ALIAS_MAP.csv').relative_to(W)),'sha256':sha(D90/'ENDPOINT_ALIAS_MAP.csv'),'commit':cfg['research_head_before']},'R5_amendment_keys':33684,'R5_amendment_keyset_sha256':digest(sorted(amendment)),'null_encoding':'Empty CSV cell remains null, never zero','all_three_CV_seeds_retained':True,'primary_split':'dev','separate_split':'test_exploratory'})
